    \label{fig:ring}
\end{figure}

Solving this system gives us the input-output relation for the ring as
\ba\label{eq:ring_IO}
\begin{pmatrix}
d_1\\
d_2
\end{pmatrix}
=
e^{i2\eta}
\begin{pmatrix}
1 & 0 \\
-\mathcal{K}_{\rm A} & 1
\end{pmatrix}
\begin{pmatrix}
c_1\\
c_2
\end{pmatrix},
\ea
where
\ba
e^{i2\eta}&=&\frac{e^{i\Omega L_{\rm A}/c}-r_{\rm A}}{1-e^{i\Omega L_{\rm A}/c}r_{\rm A}},\nonumber\\
\mathcal{K}_{\rm A}&=&
\left(
\frac{
t_{\rm A}^2
}{
1
-2\cos(\Omega L_{\rm A}/c)r_{\rm A}
+r_{\rm A}^2
}
\right)
\kappa_{\rm A}
,
\ea
with $L_A=l_1+l_2$ as the round-trip length of the ring.

For the full MZ configuration of \Cref{fig:MZ}, we need to analyze the input-output relations for both the `forward' direction (i.e., from $b_{{\rm IFO,}i}$ to $b_i$) and the `backward' direction (i.e., from $a_i$ to $a_{{\rm IFO},i}$). The relations for the forward direction can be trivially derived from~\eqref{eq:ring_IO} to be
\ba\label{eq:forward}
\begin{pmatrix}
b_1\\
b_2
\end{pmatrix}
=
e^{i2\eta}
\begin{pmatrix}
1 & 0 \\
-\mathcal{K}_{\rm A} & 1
\end{pmatrix}
\begin{pmatrix}
b_{\rm IFO,1}\\
b_{\rm IFO,2}
\end{pmatrix}.
\ea

\end{pmatrix}
\begin{pmatrix}
b_{\rm IFO,1}\\
b_{\rm IFO,2}
\end{pmatrix}.
\ea
In the limit $\Omega L_A/c\ll1$ where the cavity is short compared to a signal wavelength, and in the limit $t_{\rm A}^2\ll 1$ where M1 is highly reflecting, the forward relation reduces to~\eqref{eq:forward_approx}, whereby the results are expressed in terms of the power reflectivity $R_{\rm A}=r_{\rm A}^2$ and power transmissivity $T_{\rm A}=t_{\rm A}^2$. For the backward direction, the beam is immune to the optomechanical effect since it counter-propagates against the pump, and so the relations are like \eqref{eq:forward} but with the pump `turned off', giving
\ba\label{eq:backward}
\begin{pmatrix}
a_{\rm IFO,1}\\
a_{\rm IFO,2}
\end{pmatrix}
=
e^{i2\eta}
\begin{pmatrix}
a_{1}\\
a_{2}
\end{pmatrix}.
\ea

\end{pmatrix}
=
e^{i2\eta}
\begin{pmatrix}
a_{1}\\
a_{2}
\end{pmatrix}.
\ea
While amplitude fluctuations of the pump induce mirror displacement fluctuations that couple to the phase of the counter-propagating mode, these fluctuations can be ignored since the counter-propagating mode is weak to begin with, and the mirror's displacement is small compared to a carrier wavelength. Finally, we must also deduce the relation between the power $P_{\rm circ}$ circulating in each ring and the source power $P_{\rm source}$ of the amplifier, as labeled in~\Cref{fig:MZ}. A simplified version of the above calculation gives
\ba\label{eq:I_circ_exact}
P_{\rm circ}&=&\frac{1}{2}\left(\frac{t_{\rm A}}{1-r_{\rm A}}\right)^2P_{\rm source},
\ea
where the overall factor $1/2$ takes into account the beamsplitting at BS1. In the limit $T_{\rm A}\ll 1$ this reduces to~\eqref{eq:I_circ_approx}.

\section{Output filter cavity reflectivity}

The reflectivity of a filter cavity has been derived in Appendix A of \cite{Evans:2013}, while a more general treatment of its quadrature rotation effects were given in Appendix A of \cite{purdue2002practical}.  We have adopted the equations derived there, but due to a difference in Fourier transform convention, have used the complex conjugate of Equation A6 from \cite{Evans:2013}. Explicitly, in our calculations, the amplitude reflectivity $r_{\mathrm{fc}}(\Omega)$ of a two mirror filter cavity, for
an {\it audio sideband frequency} $\Omega$ is given by
\begin{equation}
    r_{\mathrm{fc}}(\Omega) = r_{\mathrm{in}} - \frac{t_{\mathrm{in}}^2}{r_{\mathrm{in}}} \frac{r_{\mathrm{rt}} e^{i\phi(\Omega)}}{1 - r_{\mathrm{rt}} e^{i\phi(\Omega)}},
    \label{eq:OFCrefl}
\end{equation}

where the symbols $r_{\rm rt}$, $r_{\rm in}$ and $\phi(\Omega)$ are defined in Eqs.\,A7--A8 of \cite{Evans:2013}.

where the symbols $r_{\rm rt}$, $r_{\rm in}$ and $\phi(\Omega)$ are defined in Eqs.\,A7--A8 of \cite{Evans:2013}.

Using the relation between quadrature fields $a_{1,2}(\Omega)$ and sideband fields $a(\omega_0\pm\Omega)$, Eq.~\eqref{eq:OFCrefl} allows us to calculate the phase rotation a quadrature field experiences upon reflection from the OFC, as

\begin{equation}
b_{\rm out} (\omega_0+\Omega)= r_{\rm fc}(\Omega)  b_{\rm in} (\omega_0+\Omega).
